(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.025-t*0.4)*8 + Math.cos(my*0.02+t*0.3)*6;
  const w2y = Math.cos(my*0.022+t*0.35)*8 + Math.sin(mx*0.018-t*0.25)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*40,0.085,1.8]
  ];
  let aS=0,iS=0,hS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)+Math.sin(d*f*2.1-t*sp*1.3)*0.4;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)+Math.cos(d*f*1.8+t*sp*0.8)*0.3;
    hS+=Math.sin(d*f*1.4-t*sp*0.9+0.7)*0.6+Math.sin(d*f*0.5+t*sp*1.1)*0.4;
  }
  const act=aS/8,inh=iS/8,hub=hS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.05+sy*0.01-t*0.6))/3+Math.sin((sx+sy)*0.12+t*2.5)*0.15+Math.sin((sx-sy)*0.1-t*2)*0.15+Math.sin(sx*0.08+sy*0.06-t*1.5)*0.1;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.07-ang*2+t*0.8)*0.5)*0.3;
  const coupling=Math.tanh((act-inh*0.7+hub*0.3+bg*0.25+spiral)*2.2);
  const diffusion=Math.tanh((act*inh*0.5-hub*0.3+bg*0.2)*1.8);
  const reaction=coupling*0.7+diffusion*0.3;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin((sx-sy)*0.12-t*0.7)*0.3)*1.5)*0.25;
  const grain=Math.sin(sx*0.4+t*3)*Math.sin(sy*0.4-t*2.5)*0.08;
  const blend=reaction*0.6+cell*0.2+grain*0.1+spiral*0.1,v=blend*0.5+0.5;
  const pal=[[5,12,58],[12,55,95],[18,110,120],[45,165,145],[180,185,60],[225,165,45],[215,95,55],[165,45,65],[95,25,85],[35,15,75],[5,12,58]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i,sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.85?1.2:Math.abs(reaction)>0.65?1.12:1.0;
  const depth=0.9+diffusion*0.1,chroma=hub*8;
  return[
    Math.min(255,Math.max(0,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge*depth+chroma))|0,
    Math.min(255,Math.max(0,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge*depth-chroma*0.3))|0,
    Math.min(255,Math.max(0,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge*depth+chroma*0.5))|0
  ];
}
